const snippets={"Python": ["from typing import List, Optional", "from collections import deque", "", "class Solution:", "", "    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:", "        ans = []", "        if root is None:", "            return ans", "        q = deque([root])", "        while q:", "            t = []", "            for _ in range(len(q)):", "                node = q.popleft()", "                t.append(node.val)", "                if node.left:", "                    q.append(node.left)", "                if node.right:", "                    q.append(node.right)", "            ans.append(t)", "        return ans"], "Java": ["import java.util.*;", "class Solution {", "    public List<List<Integer>> levelOrder(TreeNode root) {", "        List<List<Integer>> ans = new ArrayList<>();", "        if (root == null) {", "            return ans;", "        }", "        Deque<TreeNode> q = new ArrayDeque<>();", "        q.offer(root);", "        while (!q.isEmpty()) {", "            List<Integer> t = new ArrayList<>();", "            for (int n = q.size(); n > 0; --n) {", "                TreeNode node = q.poll();", "                t.add(node.val);", "                if (node.left != null) {", "                    q.offer(node.left);", "                }", "                if (node.right != null) {", "                    q.offer(node.right);", "                }", "            }", "            ans.add(t);", "        }", "        return ans;", "    }", "}"]};
